  const smallPayment = Math.floor(total * 0.99);
  const paid = recordPayment(invoice, { amount: smallPayment, date: '2026-09-05' }).value;

  const fee = lateFee(paid, '2026-10-07');

  assert.equal(typeof fee, 'number');
  assert.ok(fee >= 0);
});

